"use strict";function generateBreadcrumbs(){let e=document.getElementById("breadcrumbs");if(!e)return;e.innerHTML="";let t="/mmenu",n=window.location.pathname.split("/").filter(e=>e.length>0);n=n.filter(e=>"index.php"!==e&&"mmenu"!==e);let r=document.querySelector("h1"),a=r?r.textContent:document.title,i=window.location.search?window.location.search.substring(1):null,l=t,d=document.createElement("li"),c=document.createElement("a");c.href=`${t}/mmenu.php${i&&"inactivity"!==i?`?${i}`:""}`,c.textContent="Home",d.appendChild(c);let s=document.createElement("span");s.setAttribute("aria-hidden","true"),s.setAttribute("data-symbol",">"),s.textContent=" > ",d.appendChild(s),e.appendChild(d),n.forEach((t,r)=>{let d=r===n.length-1,c=capitalizeFirstLetterOfEachWord(t.replace(/-/g," "));l+=`/${t}`;let s=document.createElement("li");if(d)s.textContent=a;else{let p=document.createElement("a");p.href=`${l}/index.php${i&&"inactivity"!==i?`?${i}`:""}`,p.textContent=c,s.appendChild(p);let u=document.createElement("span");u.setAttribute("aria-hidden","true"),u.setAttribute("data-symbol",">"),u.textContent=" > ",s.appendChild(u)}e.appendChild(s)})}function capitalizeFirstLetterOfEachWord(e){return e.replace(/\b\w/g,e=>e.toUpperCase())}function insertBreadcrumbNav(){let e=document.createElement("nav");e.id="breadcrumbsMenu",e.setAttribute("aria-label","breadcrumbs");let t=document.createElement("ul");t.id="breadcrumbs",t.className="breadcrumbs",e.appendChild(t);let n=document.querySelector("main");n?n.parentNode.insertBefore(e,n):console.warn("<main> not found — breadcrumbs not inserted")}